dashboard.definition:
{
 "title": "Client Search",
 "description": "Find a client by MAC (any format), IP or name: wired and wireless, where it was last seen.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@m,now"
   }
  },
  "input_q": {
   "type": "input.text",
   "title": "Search: MAC (any format), IP or name",
   "options": {
    "token": "q",
    "defaultValue": ""
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "90s",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_clients": {
   "type": "splunk.table",
   "title": "Clients: wired and wireless, latest sighting in range. Click a row to open its switch port or wireless client",
   "dataSources": {
    "primary": "ds_clients"
   },
   "options": {
    "count": 100,
    "columnFormat": {
     "drill": {
      "hidden": true
     }
    }
   },
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "$row.drill.value$&form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
      "newTab": true
     }
    }
   ],
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_clients": {
   "type": "ds.search",
   "name": "clients",
   "options": {
    "query": "| mstats latest_time(_value) as t WHERE index=cisco_metrics metric_name=mdt_wl_client_stats_most_recent_rssi BY extracted_source traffic_stats_ms_mac_address | rename extracted_source as wlc, traffic_stats_ms_mac_address as mac | eval mac=lower(mac), prio=0, type=\"Wireless\" | sort 0 - t | dedup mac | join type=left mac [| mstats latest_time(_value) as th WHERE index=cisco_metrics metric_name=mdt_wl_info_device_hostname BY client_wsa_info_client_mac device_hostname | rename client_wsa_info_client_mac as mac, device_hostname as wl_name | eval mac=lower(mac) | sort 0 - th | dedup mac | fields mac wl_name] | join type=left mac [| mstats latest_time(_value) as ts WHERE index=cisco_metrics metric_name=mdt_wl_info_vap_ssid BY vap_ssid dot11_oper_data_ms_mac_address | rename dot11_oper_data_ms_mac_address as mac, vap_ssid as ssid | eval mac=lower(mac) | sort 0 - ts | dedup mac | fields mac ssid] | join type=left mac [| mstats latest_time(_value) as ta WHERE index=cisco_metrics metric_name=mdt_wl_client_stats_ap_mac_address BY dot11_oper_data_ms_mac_address ap_mac_address | rename dot11_oper_data_ms_mac_address as mac, ap_mac_address as eth_mac | eval mac=lower(mac), eth_mac=lower(eth_mac) | sort 0 - ta | dedup mac | fields mac eth_mac] | join type=left eth_mac [| mstats latest(_value) as x WHERE index=cisco_metrics metric_name=mdt_wl_info_eth_mac BY eth_mac ap_name_mac_map_wtp_name | rename ap_name_mac_map_wtp_name as ap_name | eval eth_mac=lower(eth_mac) | dedup eth_mac | fields eth_mac ap_name] | append [| mstats latest_time(_value) as t WHERE index=cisco_metrics metric_name=mdt_xe_mac_info_port BY extracted_source port matm_mac_entry_mac matm_mac_entry_vlan_id_number | rename extracted_source as node, matm_mac_entry_mac as mac, matm_mac_entry_vlan_id_number as vlan | append [| mstats latest_time(_value) as t WHERE index=cisco_metrics metric_name=mdt_nx_mac_info_age BY extracted_source port vlan mac | rename extracted_source as node | eval vlan=replace(vlan, \"^vlan-\", \"\")] | append [| mstats latest_time(_value) as t WHERE index=cisco_metrics metric_name=cisco.port_info BY extracted_source port mac | rename extracted_source as node] | eval mac=lower(mac) | where NOT match(port, \"(?i)^(sup|cpu)\") | eval ik=lower(node).\"|\".`mdt_ifkey(port)` | join type=left ik [| `mdt_cdp(*)` | eval ik=lower(node).\"|\".`mdt_ifkey(interface)`, is_cdp=1 | dedup ik | fields ik is_cdp] | eval prio=if(is_cdp=1, 2, 1), type=\"Wired\"] | sort 0 mac prio - t | dedup mac | join type=left mac [| mstats latest_time(_value) as ta WHERE index=cisco_metrics metric_name=mdt_xe_arp_info_hardware BY extracted_source arp_oper_address arp_vrf_vrf hardware | join type=left extracted_source arp_oper_address arp_vrf_vrf [| mstats latest_time(_value) as tm WHERE index=cisco_metrics metric_name=mdt_xe_arp_info_mode BY extracted_source arp_oper_address arp_vrf_vrf mode | where mode=\"ios-arp-mode-interface\" | eval own=1 | fields extracted_source arp_oper_address arp_vrf_vrf own] | where isnull(own) | fields arp_oper_address hardware | append [| mstats latest_time(_value) as tn WHERE index=cisco_metrics metric_name=mdt_nx_arp_info_hardware BY extracted_source arp_oper_address arp_vrf_vrf hardware | fields arp_oper_address hardware] | append [| mstats latest_time(_value) as tw WHERE index=cisco_metrics metric_name=mdt_wl_info_ip_addr BY sisf_db_mac_mac_addr ip_addr | where ip_addr!=\"0.0.0.0\" | rename ip_addr as arp_oper_address, sisf_db_mac_mac_addr as hardware | fields arp_oper_address hardware] | eval mac=lower(hardware), ip=arp_oper_address | stats values(ip) as ips by mac] | eval q=lower(trim(\"$q$\")), qh=replace(q, \"[^0-9a-f]\", \"\") | eval mac_q=if(len(qh) >= 2 AND NOT match(q, \"^[0-9]{1,3}(\\.[0-9]{1,3}){1,3}\\.?$\") AND match(q, \"^[0-9a-f:.-]+$\"), 1, 0) | eval hit_mac=if(mac_q=1 AND like(replace(mac, \"[^0-9a-f]\", \"\"), \"%\".qh.\"%\"), 1, 0) | eval hit_ip=if(like(lower(mvjoin(ips, \" \")), \"%\".q.\"%\"), 1, 0) | eval hit_name=if(like(lower(coalesce(wl_name, \"\")), \"%\".q.\"%\"), 1, 0) | where q=\"\" OR hit_mac=1 OR hit_ip=1 OR hit_name=1 | eval ip=mvindex(ips, 0) | lookup dnslookup clientip AS ip OUTPUT clienthost AS dns_name | eval Name=coalesce(wl_name, dns_name, \"-\"), IP=ips, MAC=mac, Type=type, Where=if(type=\"Wireless\", coalesce(wlc, \"-\").\" \u00b7 \".coalesce(ap_name, eth_mac, \"-\").\" \u00b7 \".coalesce(ssid, \"-\"), coalesce(node, \"-\").\" \u00b7 \".coalesce(port, \"-\").\" \u00b7 VLAN \".coalesce(vlan, \"-\")), \"Last seen\"=strftime(t, \"%Y-%m-%d %H:%M\"), drill=if(type=\"Wireless\", \"/app/mdt_infra_monitoring/wireless_client_details?form.wlc=\".wlc.\"&form.tk_client=\".mac, \"/app/mdt_infra_monitoring/interface_details?form.tk_node=\".node.\"&form.tk_interface=\".port) | sort 0 - t | table Type MAC IP Name Where \"Last seen\" drill"
   }
  }
 },
 "layout": {
  "type": "grid",
  "globalInputs": [
   "input_time",
   "input_q"
  ],
  "layoutDefinitions": {
   "layout_1": {
    "type": "grid",
    "options": {
     "width": 1440,
     "height": 700
    },
    "structure": [
     {
      "item": "viz_clients",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 1440,
       "h": 700
      }
     }
    ]
   }
  },
  "tabs": {
   "items": [
    {
     "label": "Clients",
     "layoutId": "layout_1"
    }
   ]
  }
 },
 "applicationProperties": {}
}
